-- Apply after 0001_cinste.sql. These are fictional marketplace records.
update public.offers o set localization_key = case when p.slug='cafeneaua-verde' and c.slug='food-drink' and o.name='Cappuccino' then 'cappuccino' when p.slug='cinema-luna' and c.slug='cinema' and o.name='Movie Ticket' then 'movie_ticket' when p.slug='barber-club' and c.slug='hair-grooming' and o.name='Student Haircut' then 'student_haircut' end from public.partners p, public.categories c where o.partner_id=p.id and o.category_id=c.id and o.localization_key is null and ((p.slug='cafeneaua-verde' and c.slug='food-drink' and o.name='Cappuccino') or (p.slug='cinema-luna' and c.slug='cinema' and o.name='Movie Ticket') or (p.slug='barber-club' and c.slug='hair-grooming' and o.name='Student Haircut'));
